// GET del botón del email. NO toca la base: los escáneres de correo
// (Outlook Safe Links, Proofpoint, antivirus) abren los enlaces con GET para
// revisarlos, y si este GET confirmara o cancelara, cancelarían citas solos.
// Devuelve una página que hace el POST por JavaScript al cargarse: para el
// paciente es un solo clic. Sin JavaScript, la página muestra el botón.
const q = $input.first().json.query || {};
const token = String(q.t || '').trim();
const action = String(q.a || '').trim().toLowerCase();
const LABEL = { confirm: 'Confirmar mi cita', cancel: 'Cancelar mi cita' };

const esc = (s) => String(s ?? '')
  .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;')
  .replace(/"/g, '&quot;').replace(/'/g, '&#39;');

// Mismos colores que los emails: fondo lila gris, tarjeta blanca, acento violeta.
const page = (title, cardHtml, script) => `<!doctype html>
<html lang="es"><head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width,initial-scale=1">
<meta name="robots" content="noindex,nofollow">
<title>${esc(title)}</title>
<style>
  *{box-sizing:border-box}
  body{margin:0;min-height:100vh;display:flex;align-items:center;justify-content:center;padding:24px 16px;background:#f2f0f5;font-family:'Plus Jakarta Sans',Arial,Helvetica,sans-serif;color:#0c0520}
  .card{width:100%;max-width:460px;background:#fff;border:1px solid #e4e0eb;border-radius:16px;overflow:hidden;box-shadow:0 8px 24px rgba(30,27,75,.08)}
  .bar{height:4px;background:#7a3fd9}
  .body{padding:28px 24px;text-align:center}
  .icon{width:56px;height:56px;margin:0 auto 16px;border-radius:50%;display:flex;align-items:center;justify-content:center;font-size:28px;font-weight:700}
  .ok{background:#e7f6ec;color:#1f7a3d}.warn{background:#fdf1e3;color:#a35a00}.bad{background:#fbe9ec;color:#b42339}.info{background:#f0eafb;color:#4b1d95}
  .eyebrow{margin:0 0 6px;font-size:11px;font-weight:700;letter-spacing:.08em;text-transform:uppercase;color:#4b1d95}
  h1{margin:0 0 10px;font-size:22px;line-height:1.3}
  p{margin:0 0 16px;font-size:14px;line-height:1.6;color:#3b3654}
  .details{margin:20px 0;text-align:left;background:#faf8fd;border:1px solid #e4e0eb;border-left:3px solid #4b1d95;border-radius:12px}
  .row{padding:10px 16px;border-bottom:1px solid #efedf3}.row:last-child{border-bottom:0}
  .lbl{font-size:10px;font-weight:600;letter-spacing:.08em;text-transform:uppercase;color:#6d6d78}
  .val{font-size:14px;font-weight:600;margin-top:2px}
  .btn{display:inline-block;border:0;cursor:pointer;background:#4b1d95;color:#fff;font-family:inherit;font-size:14px;font-weight:600;line-height:1;text-decoration:none;padding:13px 22px;border-radius:10px}
  .btn.secondary{background:#fff;color:#4b1d95;border:1px solid #d9d0ea}
  .muted{font-size:12px;color:#6d6d78;margin:16px 0 0}
  .spinner{width:36px;height:36px;margin:8px auto 18px;border:3px solid #e4e0eb;border-top-color:#4b1d95;border-radius:50%;animation:spin .8s linear infinite}
  @keyframes spin{to{transform:rotate(360deg)}}
</style>
</head><body>
<main class="card" aria-live="polite"><div class="bar"></div><div class="body" id="card">${cardHtml}</div></main>
${script || ''}
</body></html>`;

// Formulario que hace el POST sin JavaScript (noscript y "Reintentar").
const postForm = (token, action, label, secondary) => `<form method="post" action="" style="margin:0">
<input type="hidden" name="token" value="${esc(token)}"><input type="hidden" name="action" value="${esc(action)}">
<button type="submit" class="btn${secondary ? ' secondary' : ''}">${esc(label)}</button></form>`;

if (!/^[A-Za-z0-9_-]{20,128}$/.test(token) || !LABEL[action]) {
  const card = `<div class="icon bad">!</div><h1>Enlace no válido</h1>
<p>El enlace está incompleto. Abrilo de nuevo desde el botón del email o comunicate con la clínica.</p>`;
  return [{ json: { html: page('Enlace no válido', card, '') } }];
}

const verb = action === 'confirm' ? 'Confirmando' : 'Cancelando';
const card = `<div class="spinner" role="status" aria-label="${verb}"></div>
<h1>${verb} tu cita…</h1>
<p>Esto tarda unos segundos.</p>
<noscript><p>Tu navegador no ejecuta JavaScript. Tocá el botón para continuar.</p>${postForm(token, action, LABEL[action], action === 'cancel')}</noscript>`;

// token y action ya pasaron por la regex/lista de arriba: no traen comillas ni <.
const script = `<script>
(function () {
  var card = document.getElementById('card');
  var payload = { token: ${JSON.stringify(token)}, action: ${JSON.stringify(action)} };
  var ctrl = window.AbortController ? new AbortController() : null;
  var timer = setTimeout(function () { if (ctrl) ctrl.abort(); }, 20000);
  function failed() {
    clearTimeout(timer);
    card.innerHTML = '<div class="icon bad">!</div><h1>No pudimos procesar tu respuesta</h1>'
      + '<p>Revisá tu conexión e intentá de nuevo.</p>'
      + ${JSON.stringify(postForm(token, action, 'Reintentar', false))};
  }
  fetch(window.location.pathname, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json', 'Accept': 'application/json' },
    body: JSON.stringify(payload),
    credentials: 'omit',
    signal: ctrl ? ctrl.signal : undefined
  }).then(function (r) { return r.json(); }).then(function (d) {
    clearTimeout(timer);
    if (!d || !d.card_html) return failed();
    card.innerHTML = d.card_html;
    if (d.title) document.title = d.title;
  }).catch(failed);
})();
</script>`;

return [{ json: { html: page('Tu cita', card, script) } }];

// POST de la página (fetch JSON) o del formulario sin JavaScript
// (x-www-form-urlencoded). El token en claro solo vive en esta ejecución:
// a la base se le pregunta por su sha256.
const crypto = require('crypto');
const req = $input.first().json;
const b = req.body || {};
const h = req.headers || {};

const token = String(b.token || '').trim();
const action = String(b.action || '').trim().toLowerCase();
const contentType = String(h['content-type'] || '').toLowerCase();
// fetch manda JSON y espera JSON; el formulario espera una página.
const wantsHtml = !contentType.includes('application/json');

const ip = String(h['x-forwarded-for'] || h['x-real-ip'] || '').split(',')[0].trim().slice(0, 100);
const ua = String(h['user-agent'] || '').slice(0, 500);

const valid = /^[A-Za-z0-9_-]{20,128}$/.test(token) && ['confirm', 'cancel'].includes(action);

return [{ json: {
  token,
  action: valid ? action : '',
  // Hash vacío = la consulta responde 'invalid' sin buscar nada.
  token_hash: valid ? crypto.createHash('sha256').update(token).digest('hex') : '',
  ip,
  ua,
  wants_html: wantsHtml,
} }];

// Arma lo que ve el paciente. Para fetch: JSON { outcome, title, card_html }.
// Para el formulario sin JavaScript: la página entera.
const parsed = $('Parse Request').first().json;
const rows = $input.all().map((i) => i.json).filter((r) => r && r.outcome);
const r = rows[0] || { outcome: 'error' };

const esc = (s) => String(s ?? '')
  .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;')
  .replace(/"/g, '&quot;').replace(/'/g, '&#39;');

// Mismos colores que los emails: fondo lila gris, tarjeta blanca, acento violeta.
const page = (title, cardHtml, script) => `<!doctype html>
<html lang="es"><head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width,initial-scale=1">
<meta name="robots" content="noindex,nofollow">
<title>${esc(title)}</title>
<style>
  *{box-sizing:border-box}
  body{margin:0;min-height:100vh;display:flex;align-items:center;justify-content:center;padding:24px 16px;background:#f2f0f5;font-family:'Plus Jakarta Sans',Arial,Helvetica,sans-serif;color:#0c0520}
  .card{width:100%;max-width:460px;background:#fff;border:1px solid #e4e0eb;border-radius:16px;overflow:hidden;box-shadow:0 8px 24px rgba(30,27,75,.08)}
  .bar{height:4px;background:#7a3fd9}
  .body{padding:28px 24px;text-align:center}
  .icon{width:56px;height:56px;margin:0 auto 16px;border-radius:50%;display:flex;align-items:center;justify-content:center;font-size:28px;font-weight:700}
  .ok{background:#e7f6ec;color:#1f7a3d}.warn{background:#fdf1e3;color:#a35a00}.bad{background:#fbe9ec;color:#b42339}.info{background:#f0eafb;color:#4b1d95}
  .eyebrow{margin:0 0 6px;font-size:11px;font-weight:700;letter-spacing:.08em;text-transform:uppercase;color:#4b1d95}
  h1{margin:0 0 10px;font-size:22px;line-height:1.3}
  p{margin:0 0 16px;font-size:14px;line-height:1.6;color:#3b3654}
  .details{margin:20px 0;text-align:left;background:#faf8fd;border:1px solid #e4e0eb;border-left:3px solid #4b1d95;border-radius:12px}
  .row{padding:10px 16px;border-bottom:1px solid #efedf3}.row:last-child{border-bottom:0}
  .lbl{font-size:10px;font-weight:600;letter-spacing:.08em;text-transform:uppercase;color:#6d6d78}
  .val{font-size:14px;font-weight:600;margin-top:2px}
  .btn{display:inline-block;border:0;cursor:pointer;background:#4b1d95;color:#fff;font-family:inherit;font-size:14px;font-weight:600;line-height:1;text-decoration:none;padding:13px 22px;border-radius:10px}
  .btn.secondary{background:#fff;color:#4b1d95;border:1px solid #d9d0ea}
  .muted{font-size:12px;color:#6d6d78;margin:16px 0 0}
  .spinner{width:36px;height:36px;margin:8px auto 18px;border:3px solid #e4e0eb;border-top-color:#4b1d95;border-radius:50%;animation:spin .8s linear infinite}
  @keyframes spin{to{transform:rotate(360deg)}}
</style>
</head><body>
<main class="card" aria-live="polite"><div class="bar"></div><div class="body" id="card">${cardHtml}</div></main>
${script || ''}
</body></html>`;

// Formulario que hace el POST sin JavaScript (noscript y "Reintentar").
const postForm = (token, action, label, secondary) => `<form method="post" action="" style="margin:0">
<input type="hidden" name="token" value="${esc(token)}"><input type="hidden" name="action" value="${esc(action)}">
<button type="submit" class="btn${secondary ? ' secondary' : ''}">${esc(label)}</button></form>`;

const longDate = (iso) => {
  if (!iso) return '';
  const d = new Date(`${iso}T12:00:00Z`);
  if (isNaN(d.getTime())) return iso;
  const s = d.toLocaleDateString('es-UY', { weekday: 'long', day: 'numeric', month: 'long', timeZone: 'UTC' });
  return s.charAt(0).toUpperCase() + s.slice(1);
};

const row = (label, value) => value
  ? `<div class="row"><div class="lbl">${esc(label)}</div><div class="val">${esc(value)}</div></div>`
  : '';
const details = r.date_iso
  ? `<div class="details">${row('Fecha', longDate(r.date_iso))}${row('Hora', r.time)}${row('Profesional', r.doctor_name)}${row('Lugar', [r.sede_name, r.sede_address].filter(Boolean).join(' — '))}</div>`
  : '';

const phone = String(r.clinic_phone || '').replace(/[^\d+]/g, '');
const contact = phone
  ? `<a class="btn secondary" href="tel:${esc(phone)}">Llamar a la clínica</a>`
  : (r.clinic_email ? `<a class="btn secondary" href="mailto:${esc(r.clinic_email)}">Escribir a la clínica</a>` : '');
const clinicLine = r.clinic_name ? `<p class="muted">${esc(r.clinic_name)}</p>` : '';

const isConfirm = (r.action || parsed.action) === 'confirm';
const verbInf = isConfirm ? 'confirmar' : 'cancelar';

let icon = 'info', mark = 'i', eyebrow = '', title = '', text = '', extra = '';
switch (r.outcome) {
  case 'apply':
    if (isConfirm) {
      icon = 'ok'; mark = '✓'; eyebrow = 'Cita confirmada';
      title = '¡Gracias! Te esperamos';
      text = 'Tu cita quedó confirmada.';
    } else {
      icon = 'warn'; mark = '✕'; eyebrow = 'Cita cancelada';
      title = 'Cancelamos tu cita';
      text = 'Gracias por avisar: el horario queda libre para otra persona. Si querés agendar una nueva cita, comunicate con la clínica.';
      extra = contact;
    }
    break;
  case 'already':
    icon = isConfirm ? 'ok' : 'info'; mark = isConfirm ? '✓' : 'i';
    title = isConfirm ? 'Tu cita ya estaba confirmada' : 'Tu cita ya estaba cancelada';
    text = isConfirm ? 'No hace falta hacer nada más. Te esperamos.' : 'Si querés agendar una nueva cita, comunicate con la clínica.';
    if (!isConfirm) extra = contact;
    break;
  case 'expired':
    icon = 'warn'; mark = '!';
    title = 'Este enlace venció';
    text = `Ya no se puede ${verbInf} la cita desde el email. Si necesitás hacer un cambio, comunicate con la clínica.`;
    extra = contact;
    break;
  case 'not_allowed':
    icon = 'warn'; mark = '!';
    if (isConfirm && r.previous_status === 'cancelled') {
      title = 'Esta cita está cancelada';
      text = 'No se puede confirmar desde el email. Si querés agendar una nueva cita, comunicate con la clínica.';
    } else {
      title = `Esta cita ya no se puede ${verbInf} desde el email`;
      text = 'Si necesitás hacer un cambio, comunicate con la clínica.';
    }
    extra = contact;
    break;
  case 'invalid':
    icon = 'bad'; mark = '!';
    title = 'Enlace no válido';
    text = 'El enlace no es válido o ya no está disponible. Si necesitás hacer un cambio, comunicate con la clínica.';
    extra = contact;
    break;
  default: // 'retry' o error de la base
    icon = 'bad'; mark = '!';
    title = 'No pudimos procesar tu respuesta';
    text = 'Intentá de nuevo en unos minutos o comunicate con la clínica.';
    extra = parsed.action ? postForm(parsed.token, parsed.action, 'Reintentar', false) : contact;
}

const showDetails = ['apply', 'already', 'expired', 'not_allowed'].includes(r.outcome);
const cardHtml = `<div class="icon ${icon}">${mark}</div>
${eyebrow ? `<p class="eyebrow">${esc(eyebrow)}</p>` : ''}<h1>${esc(title)}</h1>
<p>${esc(text)}</p>
${showDetails ? details : ''}${extra}${clinicLine}`;

return [{ json: {
  wants_html: parsed.wants_html === true,
  outcome: r.outcome,
  applied: r.applied === true,
  action: r.action || parsed.action,
  appointment_id: r.appointment_id || null,
  previous_status: r.previous_status || null,
  title,
  card_html: cardHtml,
  html: page(title, cardHtml, ''),
} }];
